mapper.select:
SELECT BRAND ,KIND ,JEPMCD ,JEPMNM ,BARCD ,PRICE ,INPRICE ,FACTPRICE ,SALEPRICE ,JPMBONUS ,COMCD ,ORDERGUBUN ,JEPMSEQ ,get_date_fmt(PRDATETIME) PRDATE FROM JEPM_MST WHERE 1 = 1 AND GROUPCD = #{USER.GROUPCD}
AND CHK = 'Y'
AND CHK = 'N'
AND BRAND = #{frmBRAND}
AND KIND = #{frmKIND}
AND JEPMNM LIKE '%' + #{frmJEPMNM} + '%'
AND BARCD LIKE #{frmBARCD} + '%'
ORDER BY GROUPCD ASC,COMCD ASC,BRAND,JEPMNM

