SELECT JEPMCD CODE ,JEPMCD1 ,BRAND ,JEPMNM ,PRICE ,SALEPRICE ,BARCD FROM JEPM_MST WHERE GUBUN = #{BUSEO}
AND SENDGBN = 'Y'
AND BRAND = #{FIND}
AND JEPMNM LIKE #{FIND} + '%'
AND JEPMCD1 LIKE #{FIND} + '%'
AND CHK = 'Y'

mapper.insert:
 
	  
	  	SELECT ISNULL(MAX(CONVERT(DOUBLE,JEPMSEQ)),0) + 1 JEPMSEQ FROM JEPM_MST
	  
		INSERT INTO JEPM_MST (
		  		 GROUPCD   
		         ,GROUPNAME   
				 ,BRAND   
		         ,KIND   
		         ,JEPMCD
		         ,JEPMNM
		         ,BARCD   
		         ,PRICE     
		         ,INPRICE   
		         ,FACTPRICE   
		         ,SALEPRICE   
		         ,JPMBONUS
		         ,COMCD 
				 ,ORDERGUBUN
		         ,JEPMSEQ
		         ,PRDATETIME
		         ,PRUSERID
		         ,CHK
		)
		SELECT 
		  		#{USER.GROUPCD}   
		        ,#{USER.GROUPNAME}   
		        ,#{BRAND}
		        ,#{KIND}
		        ,#{JEPMCD}
		        ,#{JEPMNM}
		        ,#{BARCD}
		        ,#{PRICE}
		        ,#{INPRICE}
		        ,0
		        ,#{SALEPRICE}
		        ,#{JPMBONUS}
		        ,''
		        ,''
		        ,#{JEPMSEQ}
		        ,DATEFORMAT(GETDATE(),'YYYYMMDDHHNNSS')
		        ,#{USER.USERID}
		        ,'Y'
		FROM DUMMY

mapper.update:
 
		UPDATE JEPM_MST SET
				 BRAND    = #{BRAND}
		         ,KIND    = #{KIND}
		         ,JEPMCD = #{JEPMCD}
		         ,JEPMNM = #{JEPMNM}
		         ,BARCD    = #{BARCD}
		         ,PRICE      = #{PRICE}
		         ,INPRICE    = #{INPRICE}
		         ,SALEPRICE    = #{SALEPRICE}
		         ,JPMBONUS = #{JPMBONUS}
				,EDITUSERID = #{USER.USERID}
				,EDITDATETIME = DATEFORMAT(GETDATE(),'YYYYMMDDHHNNSS')
		WHERE JEPMSEQ = #{JEPMSEQ}

 
		UPDATE JEPM_MST SET
				CHK = 'N'
				,EDITUSERID = #{USER.USERID}
				,EDITDATETIME = DATEFORMAT(GETDATE(),'YYYYMMDDHHNNSS')
		WHERE JEPMSEQ = #{JEPMSEQ}
